from pathlib import Path
import concurrent.futures,csv,datetime as dt,gzip,hashlib,json,re,threading,time,urllib.request

ROOT=Path('docs/workstreams/research/AF-RES-033')
EVIDENCE=ROOT/'evidence'
REPO='rust-lang/rfcs'
NUMBERS=[2843,2845,2850,2859]
RUN_ID='opening-archive-stream-v1'
COMPRESSED_LIMIT=64*1024*1024
UNCOMPRESSED_LIMIT=1024*1024*1024
LINE_LIMIT=8*1024*1024
SECONDS_LIMIT=120
LOCK=threading.Lock()
def now():return dt.datetime.now(dt.timezone.utc).isoformat()
def append(name,row):
    with LOCK:
        with (EVIDENCE/name).open('a') as stream:
            stream.write(json.dumps(row,sort_keys=True)+'\n')
def metadata():
    selected={}
    with (ROOT/'recipient/recipient_frame.csv').open() as stream:
        for row in csv.DictReader(stream):
            number=int(row['pr_number'])
            if row['repository']==REPO and number in NUMBERS:
                selected[number]={'repository':REPO,'pr_number':number,'created_at':row['created_at']}
    candidates={number:set() for number in NUMBERS}
    with (ROOT/'recipient/recipient_attempts.jsonl').open() as stream:
        for line in stream:
            row=json.loads(line)
            if row.get('stage') in {'inspect_initial_commit','restore_snapshot'} and row.get('repository')==REPO and row.get('pr_number') in candidates:
                sha=row.get('opening_head_candidate_sha')
                if sha:candidates[row['pr_number']].add(sha)
    for number in NUMBERS:
        if number not in selected or len(candidates[number])!=1:raise ValueError('Metadata identity or candidate SHA is not unique')
        selected[number]['opening_head_candidate_sha']=next(iter(candidates[number]))
    return [selected[number] for number in NUMBERS]
class LimitError(Exception):pass
class CountingReader:
    def __init__(self,response,started):
        self.response=response;self.started=started;self.count=0;self.hasher=hashlib.sha256()
    def read(self,n=-1):
        if time.monotonic()-self.started>SECONDS_LIMIT:raise LimitError('wall-clock budget exceeded')
        if n<0:n=65536
        data=self.response.read(n)
        self.count+=len(data);self.hasher.update(data)
        if self.count>COMPRESSED_LIMIT:raise LimitError('compressed-byte budget exceeded')
        return data
def check(target):
    started=time.monotonic()
    stamp=dt.datetime.fromisoformat(target['created_at'].replace('Z','+00:00'))
    hour=f'{stamp:%Y-%m-%d}-{stamp.hour}'
    url=f'https://data.gharchive.org/{hour}.json.gz'
    attempt={'stage':'archive_stream_projection','execution_id':RUN_ID,**target,'url':url,'method':'GET','started_utc':now(),'compressed_limit':COMPRESSED_LIMIT,'uncompressed_limit':UNCOMPRESSED_LIMIT,'line_limit':LINE_LIMIT,'wall_clock_limit_seconds':SECONDS_LIMIT,'request_timeout_seconds':30,'unfiltered_event_persistence':False}
    matches=[];reader=None;lines=0;uncompressed=0;complete=False
    try:
        request=urllib.request.Request(url,headers={'User-Agent':'AF-RES-033-provenance-audit','Accept-Encoding':'identity'})
        with urllib.request.urlopen(request,timeout=30) as response:
            attempt.update(http_status=response.status,final_url=response.url,content_length=response.headers.get('Content-Length'),etag=response.headers.get('ETag'),last_modified=response.headers.get('Last-Modified'))
            if response.headers.get('Content-Length') and int(response.headers['Content-Length'])>COMPRESSED_LIMIT:
                raise LimitError('declared archive size exceeds compressed-byte budget')
            reader=CountingReader(response,started)
            with gzip.GzipFile(fileobj=reader,mode='rb') as archive:
                while True:
                    line=archive.readline(LINE_LIMIT+1)
                    if not line:complete=True;break
                    lines+=1;uncompressed+=len(line)
                    if len(line)>LINE_LIMIT:raise LimitError('single-event line budget exceeded')
                    if uncompressed>UNCOMPRESSED_LIMIT:raise LimitError('uncompressed-byte budget exceeded')
                    if time.monotonic()-started>SECONDS_LIMIT:raise LimitError('wall-clock budget exceeded')
                    if b'"PullRequestEvent"' not in line or b'"rust-lang/rfcs"' not in line:continue
                    event=json.loads(line)
                    if event.get('type')!='PullRequestEvent' or event.get('repo',{}).get('name')!=REPO:continue
                    payload=event.get('payload',{})
                    if payload.get('action')!='opened' or payload.get('number')!=target['pr_number']:continue
                    pr=payload.get('pull_request',{})
                    projected={'repository':REPO,'pr_number':payload['number'],'action':'opened','event_created_at':event.get('created_at'),'pull_request_created_at':pr.get('created_at'),'head_sha':pr.get('head',{}).get('sha'),'base_sha':pr.get('base',{}).get('sha'),'archive_line_1based':lines}
                    if projected['head_sha'] and not re.fullmatch(r'[0-9a-f]{40}',projected['head_sha']):raise ValueError('Malformed projected head SHA')
                    matches.append(projected)
        attempt['status']='scanned_complete'
    except Exception as exc:
        attempt.update(status='bounded_failure',error_type=type(exc).__name__,error=str(exc))
    attempt.update(ended_utc=now(),elapsed_seconds=round(time.monotonic()-started,3),archive_complete=complete,lines_scanned=lines,uncompressed_bytes_scanned=uncompressed,matching_event_count=len(matches))
    if reader:
        attempt['compressed_bytes_read']=reader.count
        attempt['compressed_sha256_consumed']=reader.hasher.hexdigest()
    heads=sorted({m['head_sha'] for m in matches if m.get('head_sha')})
    if not matches:status='no_match_in_scanned_hour' if complete else 'not_resolved'
    elif heads==[target['opening_head_candidate_sha']]:status='opened_event_head_matches_reconstruction'
    elif target['opening_head_candidate_sha'] not in heads:status='opened_event_head_differs_from_reconstruction'
    else:status='conflicting_opened_event_heads'
    result={'execution_id':RUN_ID,**target,'archive_url':url,'checked_utc':now(),'archive_complete':complete,'status':status,'matching_event_count':len(matches),'matches':matches,'distinct_opened_head_shas':heads,'all_event_times_equal_frame_created_at':all(m['event_created_at']==target['created_at'] for m in matches) if matches else None,'all_pr_created_times_equal_frame':all(m['pull_request_created_at']==target['created_at'] for m in matches) if matches else None,'unfiltered_event_persistence':False}
    if reader:result['compressed_sha256_consumed']=reader.hasher.hexdigest()
    append('opening-archive-attempts.jsonl',attempt)
    append('opening-archive-checks.jsonl',result)
    with LOCK:print(json.dumps(result,sort_keys=True),flush=True)
    return result
with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:
    results=list(pool.map(check,metadata()))

